import { PathLike, Stats } from 'fs';
import * as fs from 'fs/promises';
import path from 'path';
import { debug, verb } from "./cliLog";


/**
 * Throws a new error if a file does not exist. The error contains a hint if provided.
 */
function throwFileNotFoundError(type: "Folder"|"File", name?: string, hint?: string) {
    if (!name) {
        throw new Error(`${type} not found, no file name defined.${hint ? " " + hint : ""}`)
    }
    if (!name.startsWith(path.sep)) {
        throw new Error(`${type} '${name}' not found in ${process.cwd()}.${hint ? " " + hint : ""}`);
    }
    throw new Error(`${type} '${name}' not found.${hint ? " " + hint : ""}`);
}

/**
 * Ensures that a file exists and the file is not a folder. If the file does not exist, an error is thrown.
 * If the name is not provided, the error message is more specific.
 */
export async function ensureFileExists(name: string, hint?: string) {
    if (!name) {
        throwFileNotFoundError("File", name, hint);
    }
    let stat: Stats;
    try {
        stat = await fs.stat(name)
    } catch (err) {
        throwFileNotFoundError("File", name, hint)
    }
    if (!stat!.isFile()) {
        throw Error(`'${name}' is not a file.${hint ? " " + hint : ""}`)
    }
    debug(`${hint ? hint + " " : ""}'${name}' exists and is a file.`)
}

/**
 * Ensures that a file exists and the file is a folder. If the file does not exist, an error is thrown.
 */
export async function ensureFolderExists(name: string, hint?: string) {
    if (!name) {
        throwFileNotFoundError("Folder", name, hint);
    }
    let stat: Stats;
    try {
        stat = await fs.stat(name)
    } catch (err) {
        throwFileNotFoundError("Folder", name, hint)
    }
    if (!stat!.isDirectory()) {
        throw Error(`'${name}' is not a folder.${hint ? " " + hint : ""}`)
    }
    debug(`${hint ? hint + " " : ""}'${name}' exists and is a folder.`)
}

/**
 * Returns true if file exists and is a folder, otherwise false. If the name is not provided, an error is thrown with the given hint.
 */
export async function folderExists(name: string, hint?: string) {
    if (!name) {
        throw Error(`Cannot check folder existence, no name provided.${hint ? " Check option '" + hint + "'." : ""}`)
    }
    try {
        const stat = await fs.stat(name)
        return stat.isDirectory();
    } catch (err) {
        return false;
    }
}

/**
 * Returns true if file exists and is not a folder, otherwise false. If the name is not provided, an error is thrown with the given hint.
 */
export async function fileExists(name: string, hint?: string) {
    if (!name) {
        throw Error(`Cannot check folder existence, no name provided.${hint ? " Check option '" + hint + "'." : ""}`)
    }
    try {
        const stat = await fs.stat(name, {})
        return true;
    } catch (err) {
        return false;
    }
}

/**
 * Removes the folder with the given name. If the folder does not exist, nothing is done.
 * If the folder cannot be removed, an error is thrown. If the name is not provided, an error is thrown with the given hint.
 */
export async function rmDir(name: string) {
    try {
        if (await folderExists(name)) {
            verb(`Try to remove folder '${name}'.`)
            await fs.rm(name, { recursive: true, maxRetries: 0, force: true });
            verb(`Removed folder '${name}'.`)
        } else {
            verb(`Folder '${name}' not removed since it does not exist.`)
        }
    } catch (err) {
        throw Error(`Error deleting folder '${name}': ` + err);
    }
}
/**
 * Removes the file (which must not be folder) with the given name. If the file does not exist, nothing is done.
 * If the file cannot be removed, an error is thrown. If the name is not provided, an error is thrown with the given hint.
 */
export async function rmFile(name: string) {
    try {
        if (await fileExists(name)) {
            verb(`Remove file '${name}'.`)
            await fs.rm(name);
        } else {
            verb(`File '${name}' not removed since it does not exist.`)
        }
    } catch (err) {
        throw Error(`Error deleting file '${name}': ` + err);
    }
}

/**
 * Creates a folder with the given name. If the folder already exists, nothing is done.
 * If `recursive` is true, the parent folders are created as well if they do not exist. 
 */
export async function createDir(name: string, recursive = true) {
    async function doCreateDir(name: string, recursive = true) {
        try {
            await fs.mkdir(name, { recursive: recursive });
        } catch (err) {
            throw Error(`Error creating folder '${name}': ` + err);
        }
    }

    if (! await folderExists(name)) {
        verb(`Create folder '${name}'.`)
        await doCreateDir(name, recursive);
    }
}


const IGNORED_FILES = new Set<string>(['__MACOS', '.DS_Store']);

/**
 * Reads the content of a folder and returns the names of the files and/or folders in the folder.
 * macos specific files are ignored.
 */
export async function readDir(dir: string, kind: 'dir' | 'file' | 'any', recursive = false, hint: string|undefined=undefined, ignoreFiles = IGNORED_FILES): Promise<string[]> {
    await ensureFolderExists(dir, hint);
    const normalizedDir = path.join(dir); // remove "./", would be removed later on anyway causing trouble
    debug(`Read ${kind} files in '${normalizedDir}'.`)
    const subDirs = [normalizedDir];
    const entries: string[] = [];
    while (subDirs.length > 0) {
        const subDir = subDirs.pop()!; // we just checked the length;
        const dirEntries = await fs.readdir(subDir, { withFileTypes: true })
        dirEntries.forEach(dirEntry => {
            if (! ignoreFiles.has(dirEntry.name)) {
                const fullName = path.join(subDir, dirEntry.name);
                const relName = normalizedDir==="." ? fullName : fullName.substring(normalizedDir.length + 1);
                switch (kind) {
                    case 'dir': if (dirEntry.isDirectory()) entries.push(relName); break;
                    case 'file': if (dirEntry.isFile()) entries.push(relName); break;
                    case 'any': entries.push(relName); break;
                }
                if (recursive && dirEntry.isDirectory()) {
                    subDirs.push(path.join(subDir, dirEntry.name));
                }
            }
        })
    }
    return entries;
}


export async function isEmptyDir(dir: PathLike): Promise<boolean> {
    try {
        const files = await fs.readdir(dir);
        return files.length === 0;
    } catch (err) {
        throw Error(`Error checking if folder '${dir}' is empty: ` + err);
    }
}

export async function findInFolder(dir: string, extension: string, hint?: string) {
    await ensureFolderExists(dir, hint);
    const normalizedDir = path.join(dir); // remove "./", would be removed later on anyway causing trouble
    const dirEntries = await fs.readdir(dir, { withFileTypes: true })
    const res: PathLike[] = [];
    dirEntries.forEach(dirEntry => {
        if (dirEntry.isFile() && dirEntry.name.endsWith(extension)) {
            const fullName = path.join(dir, dirEntry.name);
            res.push(path.join(normalizedDir, dirEntry.name));
        }
    })
    return res;
}

export async function findDirContainingFile(startDir: string, containingFile: string, ignoredDirs: string[]) {
    if (!containingFile || containingFile.length == 0) {
        throw new Error(`No project file provided, cannot find project in '${startDir}`);
    }
    await ensureFolderExists(startDir)
    const entries: string[] = [];
    const subDirs = [startDir];
    for (const subDir of subDirs) {
        const dirEntries = await fs.readdir(subDir, { withFileTypes: true })
        for (const dirEntry of dirEntries) {
            if (!IGNORED_FILES.has(dirEntry.name)) {
                if (dirEntry.name == containingFile) {
                    return subDir;
                }
                if (dirEntry.isDirectory()
                    && !dirEntry.name.startsWith('.')
                    && !ignoredDirs.includes(dirEntry.name)) {
                    subDirs.push(path.join(subDir, dirEntry.name));
                }
            }
        }
    }
    throw new Error(`Did not find ${containingFile} in any sub-folder of ${startDir}.`);
}


export async function findDirsInPathToRoot(startDir: string, dirToFind: string) {
    if (!dirToFind || dirToFind.length == 0) {
        throw new Error(`No dir to file provided, cannot find it '${startDir}`);
    }
    const foundDirs = []
    await ensureFolderExists(startDir)
    startDir = path.resolve(startDir);
    let currentDir = startDir;
    do {
        const dirEntries = await fs.readdir(startDir, { withFileTypes: true })
        for (const dirEntry of dirEntries) {
            if (dirEntry.name == dirToFind && dirEntry.isDirectory()) {
                foundDirs.unshift(path.join(startDir, dirToFind));
                break;
            }
        }
        currentDir = startDir
        startDir = path.dirname(startDir);
    } while (startDir != currentDir);

    return foundDirs;
}

export function absPath(file: string) {
    let resolved = path.resolve(file);
    if (!resolved) {
        resolved = path.resolve(path.join('.', file));
    }
    if (!resolved) {
        throw new Error(`Cannot resolve absolute path of ${file} in ${process.cwd}.`)
    }
    return resolved;
}


